package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject.PatternVO;

class PatternValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of pattern of observed fingerprint rule")
  void test_pattern_value_holder_assign_plain_value() {
    Object holder = new Object();
    PatternValueHolder<Object> value = new PatternValueHolder<>(holder);
    Assertions.assertSame(holder, value.pattern("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPatternValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getPattern().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of pattern of observed fingerprint rule")
  void test_pattern_value_holder_assign_value_object() {
    Object holder = new Object();
    PatternValueHolder<Object> value = new PatternValueHolder<>(holder);
    PatternVO vo = PatternVO.from("one");
    Assertions.assertFalse(value.getPatternValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.pattern(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPatternValue().orElseThrow());
    Assertions.assertSame(holder, value.pattern(Optional.empty()));
    Assertions.assertFalse(value.getPatternValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.pattern(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPatternValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of pattern of observed fingerprint rule against the original")
  void test_pattern_value_holder_read() {
    Object holder = new Object();
    PatternValueHolder<Object> value = new PatternValueHolder<>(holder);
    PatternVO vo = PatternVO.from("one");
    PatternVO other = PatternVO.from("one");
    ObservedFingerprintRule original = Mockito.mock(ObservedFingerprintRule.class);
    Mockito.when(original.getPatternValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPattern(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readPattern(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.pattern(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPattern(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPattern(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of pattern of observed fingerprint rule")
  void test_pattern_value_holder_unset() {
    Object holder = new Object();
    PatternValueHolder<Object> value = new PatternValueHolder<>(holder);
    PatternVO vo = PatternVO.from("one");
    value.pattern(vo);
    Assertions.assertSame(holder, value.unsetPatternIfMatches("pattern_other"));
    Assertions.assertTrue(value.getPatternValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPatternIfMatches("pattern"));
    Assertions.assertFalse(value.getPatternValue().isPresent(),
        "The field name must clear the value");
    value.pattern(vo);
    Assertions.assertSame(holder, value.unsetPattern());
    Assertions.assertFalse(value.getPatternValue().isPresent(), "Unset must clear the value");
  }
}
